   100→    }
   101→
   102→    let backupCreated: string | undefined;
   103→
   104→    // Create backup before import if requested
   105→    if (options.createBackupBeforeImport && deps.gatherBackupData) {
   106→      backupCreated = await createPreImportBackup(deps);
